71: func (k kubernetes) Get(ctx context.Context, key string, opts GetOptions) (resp KubernetesGetResponse, err error) {
72: 	rangeResp, err := k.kv.Range(ctx, getRequest(key, opts.Revision))
73: 	if err != nil {
74: 		return resp, toErr(ctx, err)
75: 	}
76: 	resp.Revision = rangeResp.Header.Revision
77: 	if len(rangeResp.Kvs) == 1 {
78: 		resp.KV = rangeResp.Kvs[0]
79: 	}
80: 	return resp, nil
81: }
