83: func (k kubernetes) List(ctx context.Context, prefix string, opts ListOptions) (resp KubernetesListResponse, err error) {
84: 	rangeStart := prefix + opts.Continue
85: 	rangeEnd := GetPrefixRangeEnd(prefix)
86: 
87: 	rangeResp, err := k.kv.Range(ctx, &pb.RangeRequest{
88: 		Key:      []byte(rangeStart),
89: 		RangeEnd: []byte(rangeEnd),
90: 		Limit:    opts.Limit,
91: 		Revision: opts.Revision,
92: 	})
93: 	if err != nil {
94: 		return resp, toErr(ctx, err)
95: 	}
96: 	resp.KVs = rangeResp.Kvs
97: 	resp.Count = rangeResp.Count
98: 	resp.Revision = rangeResp.Header.Revision
99: 	return resp, nil
100: }
