102: func (k kubernetes) Count(ctx context.Context, prefix string) (int64, error) {
103: 	resp, err := k.kv.Range(ctx, &pb.RangeRequest{
104: 		Key:       []byte(prefix),
105: 		RangeEnd:  []byte(GetPrefixRangeEnd(prefix)),
106: 		CountOnly: true,
107: 	})
108: 	if err != nil {
109: 		return 0, toErr(ctx, err)
110: 	}
111: 	return resp.Count, nil
112: }
