114: func (k kubernetes) OptimisticPut(ctx context.Context, key string, value []byte, opts PutOptions) (resp KubernetesPutResponse, err error) {
115: 	onSuccess := &pb.RequestOp{Request: &pb.RequestOp_RequestPut{RequestPut: &pb.PutRequest{Key: []byte(key), Value: value, Lease: int64(opts.LeaseID)}}}
116: 
117: 	var onFailure *pb.RequestOp
118: 	if opts.GetOnFailure {
119: 		onFailure = &pb.RequestOp{Request: &pb.RequestOp_RequestRange{RequestRange: getRequest(key, 0)}}
120: 	}
121: 
122: 	txnResp, err := k.optimisticTxn(ctx, key, opts.ExpectedRevision, onSuccess, onFailure)
123: 	if err != nil {
124: 		return resp, toErr(ctx, err)
125: 	}
126: 	resp.Succeeded = txnResp.Succeeded
127: 	resp.Revision = txnResp.Header.Revision
128: 	if opts.GetOnFailure && !txnResp.Succeeded {
129: 		resp.KV = kvFromTxnResponse(txnResp.Responses[0])
130: 	}
131: 	return resp, nil
132: }
133: 
134: func (k kubernetes) OptimisticDelete(ctx context.Context, key string, opts DeleteOptions) (resp KubernetesDeleteResponse, err error) {
135: 	onSuccess := &pb.RequestOp{Request: &pb.RequestOp_RequestDeleteRange{RequestDeleteRange: &pb.DeleteRangeRequest{Key: []byte(key)}}}
136: 
137: 	var onFailure *pb.RequestOp
138: 	if opts.GetOnFailure {
139: 		onFailure = &pb.RequestOp{Request: &pb.RequestOp_RequestRange{RequestRange: getRequest(key, 0)}}
140: 	}
141: 
142: 	txnResp, err := k.optimisticTxn(ctx, key, opts.ExpectedRevision, onSuccess, onFailure)
143: 	if err != nil {
144: 		return resp, toErr(ctx, err)
145: 	}
146: 	resp.Succeeded = txnResp.Succeeded
147: 	resp.Revision = txnResp.Header.Revision
148: 	if opts.GetOnFailure && !txnResp.Succeeded {
149: 		resp.KV = kvFromTxnResponse(txnResp.Responses[0])
150: 	}
151: 	return resp, nil
152: }
153: 
154: func (k kubernetes) optimisticTxn(ctx context.Context, key string, expectRevision int64, onSuccess, onFailure *pb.RequestOp) (*pb.TxnResponse, error) {
155: 	txn := &pb.TxnRequest{
156: 		Compare: []*pb.Compare{
157: 			{
158: 				Result:      pb.Compare_EQUAL,
159: 				Target:      pb.Compare_MOD,
160: 				Key:         []byte(key),
161: 				TargetUnion: &pb.Compare_ModRevision{ModRevision: expectRevision},
162: 			},
163: 		},
164: 	}
165: 	if onSuccess != nil {
166: 		txn.Success = []*pb.RequestOp{onSuccess}
167: 	}
168: 	if onFailure != nil {
169: 		txn.Failure = []*pb.RequestOp{onFailure}
170: 	}
171: 	return k.kv.Txn(ctx, txn)
172: }
173: 
174: func getRequest(key string, revision int64) *pb.RangeRequest {
175: 	return &pb.RangeRequest{
176: 		Key:      []byte(key),
177: 		Revision: revision,
178: 		Limit:    1,
179: 	}
180: }
181: 
182: func kvFromTxnResponse(resp *pb.ResponseOp) *mvccpb.KeyValue {
183: 	getResponse := resp.GetResponseRange()
184: 	if len(getResponse.Kvs) == 1 {
185: 		return getResponse.Kvs[0]
186: 	}
187: 	return nil
188: }

