80: // New creates a new etcdv3 client from a given configuration.
81: func New(cfg Config) (*Client, error) {
82: 	if len(cfg.Endpoints) == 0 {
83: 		return nil, ErrNoAvailableEndpoints
84: 	}
85: 
86: 	return newClient(&cfg)
