89: // NewCtxClient creates a client with a context but no underlying grpc
90: // connection. This is useful for embedded cases that override the
91: // service interface implementations and do not need connection management.
92: func NewCtxClient(ctx context.Context, opts ...Option) *Client {
93: 	cctx, cancel := context.WithCancel(ctx)
94: 	c := &Client{ctx: cctx, cancel: cancel, lgMu: new(sync.RWMutex), epMu: new(sync.RWMutex)}
95: 	for _, opt := range opts {
96: 		opt(c)
97: 	}
98: 	if c.lg == nil {
99: 		c.lg = zap.NewNop()
100: 	}
101: 	return c
102: }
103: 
104: // Option is a function type that can be passed as argument to NewCtxClient to configure client
105: type Option func(*Client)
106: 
107: // NewFromURL creates a new etcdv3 client from a URL.
108: func NewFromURL(url string) (*Client, error) {
109: 	return New(Config{Endpoints: []string{url}})
110: }
