185: // Sync synchronizes client's endpoints with the known endpoints from the etcd membership.
186: func (c *Client) Sync(ctx context.Context) error {
187: 	mresp, err := c.MemberList(ctx)
188: 	if err != nil {
189: 		return err
190: 	}
191: 	var eps []string
192: 	for _, m := range mresp.Members {
193: 		if len(m.Name) != 0 && !m.IsLearner {
194: 			eps = append(eps, m.ClientURLs...)
195: 		}
196: 	}
197: 	c.SetEndpoints(eps...)
198: 	c.lg.Debug("set etcd endpoints by autoSync", zap.Strings("endpoints", eps))
199: 	return nil
200: }
201: 
202: func (c *Client) autoSync() {
203: 	if c.cfg.AutoSyncInterval == time.Duration(0) {
204: 		return
205: 	}
206: 
207: 	for {
208: 		select {
209: 		case <-c.ctx.Done():
210: 			return
211: 		case <-time.After(c.cfg.AutoSyncInterval):
212: 			ctx, cancel := context.WithTimeout(c.ctx, 5*time.Second)
213: 			err := c.Sync(ctx)
214: 			cancel()
215: 			if err != nil && err != c.ctx.Err() {
216: 				c.lg.Info("Auto sync endpoints failed.", zap.Error(err))
217: 			}
218: 		}
219: 	}
220: }
