222: // dialSetupOpts gives the dial opts prior to any authentication.
223: func (c *Client) dialSetupOpts(creds grpccredentials.TransportCredentials, dopts ...grpc.DialOption) []grpc.DialOption {
224: 	var opts []grpc.DialOption
225: 
226: 	if c.cfg.DialKeepAliveTime > 0 {
227: 		params := keepalive.ClientParameters{
228: 			Time:                c.cfg.DialKeepAliveTime,
229: 			Timeout:             c.cfg.DialKeepAliveTimeout,
230: 			PermitWithoutStream: c.cfg.PermitWithoutStream,
231: 		}
232: 		opts = append(opts, grpc.WithKeepaliveParams(params))
233: 	}
234: 	opts = append(opts, dopts...)
235: 
236: 	if creds != nil {
237: 		opts = append(opts, grpc.WithTransportCredentials(creds))
238: 	} else {
239: 		opts = append(opts, grpc.WithTransportCredentials(insecure.NewCredentials()))
240: 	}
241: 
242: 	unaryMaxRetries := defaultUnaryMaxRetries
243: 	if c.cfg.MaxUnaryRetries > 0 {
244: 		unaryMaxRetries = c.cfg.MaxUnaryRetries
245: 	}
246: 
247: 	backoffWaitBetween := defaultBackoffWaitBetween
248: 	if c.cfg.BackoffWaitBetween > 0 {
249: 		backoffWaitBetween = c.cfg.BackoffWaitBetween
250: 	}
251: 
252: 	backoffJitterFraction := defaultBackoffJitterFraction
253: 	if c.cfg.BackoffJitterFraction > 0 {
254: 		backoffJitterFraction = c.cfg.BackoffJitterFraction
255: 	}
256: 
257: 	// Interceptor retry and backoff.
258: 	// TODO: Replace all of clientv3/retry.go with RetryPolicy:
259: 	// https://github.com/grpc/grpc-proto/blob/cdd9ed5c3d3f87aef62f373b93361cf7bddc620d/grpc/service_config/service_config.proto#L130
260: 	rrBackoff := withBackoff(c.roundRobinQuorumBackoff(backoffWaitBetween, backoffJitterFraction))
261: 	opts = append(opts,
262: 		// Disable stream retry by default since go-grpc-middleware/retry does not support client streams.
263: 		// Streams that are safe to retry are enabled individually.
264: 		grpc.WithStreamInterceptor(c.streamClientInterceptor(withMax(0), rrBackoff)),
265: 		grpc.WithUnaryInterceptor(c.unaryClientInterceptor(withMax(unaryMaxRetries), rrBackoff)),
266: 	)
267: 
268: 	return opts
269: }
