271: // Dial connects to a single endpoint using the client's config.
272: func (c *Client) Dial(ep string) (*grpc.ClientConn, error) {
273: 	creds := c.credentialsForEndpoint(ep)
274: 
275: 	// Using ad-hoc created resolver, to guarantee only explicitly given
276: 	// endpoint is used.
277: 	return c.dial(creds, grpc.WithResolvers(resolver.New(ep)))
278: }
