280: func (c *Client) getToken(ctx context.Context) error {
281: 	var err error // return last error in a case of fail
282: 
283: 	if c.Username == "" || c.Password == "" {
284: 		return nil
285: 	}
286: 
287: 	resp, err := c.Auth.Authenticate(ctx, c.Username, c.Password)
288: 	if err != nil {
289: 		if err == rpctypes.ErrAuthNotEnabled {
290: 			c.authTokenBundle.UpdateAuthToken("")
291: 			return nil
292: 		}
293: 		return err
294: 	}
295: 	c.authTokenBundle.UpdateAuthToken(resp.Token)
296: 	return nil
297: }
