299: // dialWithBalancer dials the client's current load balanced resolver group.  The scheme of the host
300: // of the provided endpoint determines the scheme used for all endpoints of the client connection.
301: func (c *Client) dialWithBalancer(dopts ...grpc.DialOption) (*grpc.ClientConn, error) {
302: 	creds := c.credentialsForEndpoint(c.Endpoints()[0])
303: 	opts := append(dopts, grpc.WithResolvers(c.resolver))
304: 	return c.dial(creds, opts...)
305: }
306: 
307: // dial configures and dials any grpc balancer target.
308: func (c *Client) dial(creds grpccredentials.TransportCredentials, dopts ...grpc.DialOption) (*grpc.ClientConn, error) {
309: 	opts := c.dialSetupOpts(creds, dopts...)
310: 
311: 	if c.authTokenBundle != nil {
312: 		opts = append(opts, grpc.WithPerRPCCredentials(c.authTokenBundle.PerRPCCredentials()))
313: 	}
314: 
315: 	opts = append(opts, c.cfg.DialOptions...)
316: 
317: 	dctx := c.ctx
318: 	if c.cfg.DialTimeout > 0 {
319: 		var cancel context.CancelFunc
320: 		dctx, cancel = context.WithTimeout(c.ctx, c.cfg.DialTimeout)
321: 		defer cancel() // TODO: Is this right for cases where grpc.WithBlock() is not set on the dial options?
322: 	}
323: 	target := fmt.Sprintf("%s://%p/%s", resolver.Schema, c, authority(c.endpoints[0]))
324: 	conn, err := grpc.DialContext(dctx, target, opts...)
325: 	if err != nil {
326: 		return nil, err
327: 	}
328: 	return conn, nil
329: }
