331: func authority(endpoint string) string {
332: 	spl := strings.SplitN(endpoint, "://", 2)
333: 	if len(spl) < 2 {
334: 		if strings.HasPrefix(endpoint, "unix:") {
335: 			return endpoint[len("unix:"):]
336: 		}
337: 		if strings.HasPrefix(endpoint, "unixs:") {
338: 			return endpoint[len("unixs:"):]
339: 		}
340: 		return endpoint
341: 	}
342: 	return spl[1]
343: }
