345: func (c *Client) credentialsForEndpoint(ep string) grpccredentials.TransportCredentials {
346: 	r := endpoint.RequiresCredentials(ep)
347: 	switch r {
348: 	case endpoint.CredsDrop:
349: 		return nil
350: 	case endpoint.CredsOptional:
351: 		return c.creds
352: 	case endpoint.CredsRequire:
353: 		if c.creds != nil {
354: 			return c.creds
355: 		}
356: 		return credentials.NewTransportCredential(nil)
357: 	default:
358: 		panic(fmt.Errorf("unsupported CredsRequirement: %v", r))
359: 	}
360: }
