362: func newClient(cfg *Config) (*Client, error) {
363: 	if cfg == nil {
364: 		cfg = &Config{}
365: 	}
366: 	var creds grpccredentials.TransportCredentials
367: 	if cfg.TLS != nil {
368: 		creds = credentials.NewTransportCredential(cfg.TLS)
369: 	}
370: 
371: 	// use a temporary skeleton client to bootstrap first connection
372: 	baseCtx := context.TODO()
373: 	if cfg.Context != nil {
374: 		baseCtx = cfg.Context
375: 	}
376: 
377: 	ctx, cancel := context.WithCancel(baseCtx)
378: 	client := &Client{
379: 		conn:     nil,
380: 		cfg:      *cfg,
381: 		creds:    creds,
382: 		ctx:      ctx,
383: 		cancel:   cancel,
384: 		epMu:     new(sync.RWMutex),
385: 		callOpts: defaultCallOpts,
386: 		lgMu:     new(sync.RWMutex),
387: 	}
388: 
389: 	var err error
390: 	if cfg.Logger != nil {
391: 		client.lg = cfg.Logger
392: 	} else if cfg.LogConfig != nil {
393: 		client.lg, err = cfg.LogConfig.Build()
394: 	} else {
395: 		client.lg, err = logutil.CreateDefaultZapLogger(etcdClientDebugLevel())
396: 		if client.lg != nil {
397: 			client.lg = client.lg.Named("etcd-client")
398: 		}
399: 	}
400: 	if err != nil {
401: 		return nil, err
402: 	}
403: 
404: 	if cfg.Username != "" && cfg.Password != "" {
405: 		client.Username = cfg.Username
406: 		client.Password = cfg.Password
407: 		client.authTokenBundle = credentials.NewPerRPCCredentialBundle()
408: 	}
409: 	if cfg.MaxCallSendMsgSize > 0 || cfg.MaxCallRecvMsgSize > 0 {
410: 		if cfg.MaxCallRecvMsgSize > 0 && cfg.MaxCallSendMsgSize > cfg.MaxCallRecvMsgSize {
411: 			return nil, fmt.Errorf("gRPC message recv limit (%d bytes) must be greater than send limit (%d bytes)", cfg.MaxCallRecvMsgSize, cfg.MaxCallSendMsgSize)
412: 		}
413: 		callOpts := []grpc.CallOption{
414: 			defaultWaitForReady,
415: 			defaultMaxCallSendMsgSize,
416: 			defaultMaxCallRecvMsgSize,
417: 		}
418: 		if cfg.MaxCallSendMsgSize > 0 {
419: 			callOpts[1] = grpc.MaxCallSendMsgSize(cfg.MaxCallSendMsgSize)
420: 		}
421: 		if cfg.MaxCallRecvMsgSize > 0 {
422: 			callOpts[2] = grpc.MaxCallRecvMsgSize(cfg.MaxCallRecvMsgSize)
423: 		}
424: 		client.callOpts = callOpts
425: 	}
426: 
427: 	client.resolver = resolver.New(cfg.Endpoints...)
428: 
429: 	if len(cfg.Endpoints) < 1 {
430: 		client.cancel()
431: 		return nil, errors.New("at least one Endpoint is required in client config")
432: 	}
433: 	client.SetEndpoints(cfg.Endpoints...)
434: 
435: 	// Use a provided endpoint target so that for https:// without any tls config given, then
436: 	// grpc will assume the certificate server name is the endpoint host.
437: 	conn, err := client.dialWithBalancer()
438: 	if err != nil {
439: 		client.cancel()
440: 		client.resolver.Close()
441: 		// TODO: Error like `fmt.Errorf(dialing [%s] failed: %v, strings.Join(cfg.Endpoints, ";"), err)` would help with debugging a lot.
442: 		return nil, err
443: 	}
444: 	client.conn = conn
445: 
446: 	client.Cluster = NewCluster(client)
